/**
 * Policy Clause Templates — Development & Change (p47-p48), Physical Security (p49), AI (p50)
 * Based on ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, NIS2 Art.21
 *
 * Consolidation rules applied:
 * - p47 owns: CI/CD pipeline security (c12), IaC security scanning (c11)
 * - p48 owns: Release management (c13), change-process governance
 * - p47 delegates: Developer training → p44, App logging → p27, Auth implementation → p11
 * - p48 delegates: CI/CD hardening → p47-c12, IaC change control → p47-c11, CM training → p44, Patch ops → p22
 * - p49 delegates: Secure disposal → p24, Secure meeting rooms → p25
 * - p50 consolidates: AI Incident Mgmt + Response → single c17; Model Versioning + Lifecycle → single c10
 * - p50 delegates: AI training → p44, AI provider management → p42/p43
 *
 * @module devChangePhysicalAI
 */
import type { PolicyClause } from "../policyClauseTemplates";

export const devChangePhysicalAIClauses: Record<string, PolicyClause[]> = {
  /* ═══════════════════════════════════════════════════════════════
   * p47 — Secure Development Policy (18 clauses)
   * Canonical owner: CI/CD security (c12), IaC security (c11)
   * Delegates: Auth impl → p11, App logging → p27, Dev training → p44
   * ═══════════════════════════════════════════════════════════════ */
  p47: [
    { id: "p47-c00", title: "Zweck und Geltungsbereich der sicheren Entwicklungsrichtlinie", titleEn: "Purpose & Scope of Secure Development Policy", description: "Diese Richtlinie definiert die Sicherheitsanforderungen für den gesamten Softwareentwicklungslebenszyklus (SDLC). Sie gilt für alle intern und extern entwickelten Anwendungen und umfasst Anforderungsanalyse, Design, Implementierung, Test, Deployment und Wartung.", descriptionEn: "This policy defines security requirements for the entire Software Development Lifecycle (SDLC). It applies to all internally and externally developed applications covering requirements, design, implementation, testing, deployment, and maintenance.", reason: "Sicherheit muss von Anfang an in die Entwicklung integriert werden (Shift Left). Nachträgliches Patching ist teurer und weniger wirksam.", reasonEn: "Security must be integrated into development from the start (Shift Left). Retrofitting patches is more expensive and less effective.", whenRequired: "Erforderlich für alle Organisationen mit Softwareentwicklung.", whenRequiredEn: "Required for all organisations with software development.", sources: ["ISO 27001:2022 A.8.25-8.31", "NIS2 Art.21(2)(e)", "BSI IT-Grundschutz CON.8", "NIST CSF 2.0 PR.DS"] },
    { id: "p47-c01", title: "Secure-by-Design-Prinzipien", titleEn: "Secure-by-Design Principles", description: "Anwendungen müssen nach Secure-by-Design-Prinzipien entwickelt werden: Minimale Angriffsfläche, Defence-in-Depth, Principle of Least Privilege, sichere Standardkonfigurationen, Eingabevalidierung, Fehlerbehandlung ohne Informationsleck und kryptographisch sichere Zufallszahlen. Sicherheitsanforderungen müssen in der Anforderungsphase definiert werden.", descriptionEn: "Applications must be developed following secure-by-design principles: minimal attack surface, defence-in-depth, least privilege, secure defaults, input validation, error handling without information leaks, and cryptographically secure random numbers. Security requirements must be defined in the requirements phase.", reason: "Sicherheitsarchitektur-Entscheidungen in der Designphase haben den größten Einfluss auf die Gesamtsicherheit.", reasonEn: "Security architecture decisions during the design phase have the greatest impact on overall security.", whenRequired: "Erforderlich für alle neuen Entwicklungsprojekte.", whenRequiredEn: "Required for all new development projects.", sources: ["ISO 27001:2022 A.8.25", "BSI IT-Grundschutz CON.8", "OWASP SAMM"] },
    { id: "p47-c02", title: "Sichere Programmierstandards", titleEn: "Secure Coding Standards", description: "Wir müssen sichere Programmierstandards für alle verwendeten Programmiersprachen definieren. Die Standards müssen die OWASP Top 10, SANS CWE Top 25 und sprachspezifische Best Practices berücksichtigen. Code muss gegen Injection, XSS, CSRF, Broken Authentication und andere verbreitete Schwachstellen geschützt sein.", descriptionEn: "We must define secure coding standards for all programming languages used. Standards must address OWASP Top 10, SANS CWE Top 25, and language-specific best practices. Code must be protected against injection, XSS, CSRF, broken authentication, and other common vulnerabilities.", reason: "Die meisten Schwachstellen entstehen durch unsichere Programmierpraktiken. Standards verhindern bekannte Fehlerklassen.", reasonEn: "Most vulnerabilities arise from insecure coding practices. Standards prevent known error classes.", whenRequired: "Erforderlich für alle Entwicklungsaktivitäten.", whenRequiredEn: "Required for all development activities.", sources: ["ISO 27001:2022 A.8.28", "BSI IT-Grundschutz CON.8", "OWASP Top 10", "SANS CWE Top 25"] },
    { id: "p47-c03", title: "Code-Review und Peer-Review", titleEn: "Code Review & Peer Review", description: "Alle Code-Änderungen müssen vor dem Merge einem Peer-Review unterzogen werden. Reviews müssen Sicherheitsaspekte explizit berücksichtigen. Für sicherheitskritische Komponenten müssen dedizierte Security-Reviews durch geschultes Personal durchgeführt werden. Review-Checklisten müssen die OWASP-Top-10-Kategorien abdecken.", descriptionEn: "All code changes must undergo peer review before merge. Reviews must explicitly consider security aspects. For security-critical components, dedicated security reviews must be conducted by trained personnel. Review checklists must cover OWASP Top 10 categories.", reason: "Code-Reviews sind das effektivste Mittel zur Erkennung von Sicherheitsschwachstellen im Code vor der Produktion.", reasonEn: "Code reviews are the most effective means for detecting security vulnerabilities in code before production.", whenRequired: "Erforderlich für alle Code-Änderungen.", whenRequiredEn: "Required for all code changes.", sources: ["ISO 27001:2022 A.8.28", "BSI IT-Grundschutz CON.8", "NIST CSF 2.0 PR.DS"] },
    { id: "p47-c04", title: "Automatisierte Sicherheitstests (SAST/DAST/SCA)", titleEn: "Automated Security Testing (SAST/DAST/SCA)", description: "Automatisierte Sicherheitstests müssen in die CI/CD-Pipeline integriert werden: SAST (Static Application Security Testing) bei jedem Build, DAST (Dynamic Application Security Testing) vor jedem Release, SCA (Software Composition Analysis) für Abhängigkeiten. Kritische Findings müssen den Build blockieren.", descriptionEn: "Automated security testing must be integrated into the CI/CD pipeline: SAST at every build, DAST before every release, SCA for dependencies. Critical findings must block the build.", reason: "Manuelle Tests allein skalieren nicht. Automatisierung erkennt Schwachstellen frühzeitig und konsistent.", reasonEn: "Manual testing alone does not scale. Automation detects vulnerabilities early and consistently.", whenRequired: "Erforderlich für alle CI/CD-Pipelines.", whenRequiredEn: "Required for all CI/CD pipelines.", sources: ["ISO 27001:2022 A.8.29", "BSI IT-Grundschutz CON.8", "NIST CSF 2.0 PR.DS"] },
    { id: "p47-c05", title: "Trennung von Entwicklungs-, Test- und Produktionsumgebungen", titleEn: "Separation of Dev, Test & Production Environments", description: "Entwicklungs-, Test- und Produktionsumgebungen müssen strikt getrennt sein. Produktionsdaten dürfen nicht unverändert in Test- oder Entwicklungsumgebungen verwendet werden (Anonymisierung/Pseudonymisierung erforderlich). Zugangsberechtigungen müssen für jede Umgebung separat verwaltet werden.", descriptionEn: "Development, test, and production environments must be strictly separated. Production data must not be used unchanged in test or development environments (anonymisation/pseudonymisation required). Access permissions must be managed separately for each environment.", reason: "Ohne Trennung können Entwicklungsfehler die Produktion beeinträchtigen und Produktionsdaten in unsicheren Umgebungen exponiert werden.", reasonEn: "Without separation, development errors can affect production and production data can be exposed in insecure environments.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.31", "BSI IT-Grundschutz CON.8", "NIST CSF 2.0 PR.DS"] },
    { id: "p47-c06", title: "Dependency- und Open-Source-Management", titleEn: "Dependency & Open Source Management", description: "Open-Source-Komponenten und Bibliotheken müssen inventarisiert (SBOM) und auf bekannte Schwachstellen überwacht werden. Veraltete oder verwundbare Abhängigkeiten müssen zeitnah aktualisiert werden. Lizenzen von Open-Source-Komponenten müssen geprüft und kompatibel sein. Automatische Vulnerability-Alerts für Abhängigkeiten müssen konfiguriert sein.", descriptionEn: "Open-source components and libraries must be inventoried (SBOM) and monitored for known vulnerabilities. Outdated or vulnerable dependencies must be promptly updated. Licences of open-source components must be reviewed and compatible. Automatic vulnerability alerts for dependencies must be configured.", reason: "Open-Source-Schwachstellen (z.B. Log4j) können die gesamte Anwendung kompromittieren. Ohne Inventar und Monitoring bleiben sie unentdeckt.", reasonEn: "Open-source vulnerabilities (e.g., Log4j) can compromise the entire application. Without inventory and monitoring, they remain undetected.", whenRequired: "Erforderlich für alle Projekte mit externen Abhängigkeiten.", whenRequiredEn: "Required for all projects with external dependencies.", sources: ["NIS2 Art.21(2)(d)", "ISO 27001:2022 A.8.28", "NIST CSF 2.0 GV.SC", "CRA"] },
    { id: "p47-c07", title: "Secrets-Management", titleEn: "Secrets Management", description: "API-Schlüssel, Passwörter, Tokens und Zertifikate dürfen niemals im Quellcode gespeichert werden. Ein dediziertes Secrets-Management-System (z.B. Vault) muss eingesetzt werden. Secrets müssen regelmäßig rotiert werden. Pre-commit-Hooks müssen das versehentliche Einchecken von Secrets verhindern.", descriptionEn: "API keys, passwords, tokens, and certificates must never be stored in source code. A dedicated secrets management system (e.g., Vault) must be used. Secrets must be regularly rotated. Pre-commit hooks must prevent accidental check-in of secrets.", reason: "Im Quellcode exponierte Secrets sind einer der häufigsten Gründe für Sicherheitsverletzungen.", reasonEn: "Secrets exposed in source code are one of the most common reasons for security breaches.", whenRequired: "Erforderlich für alle Entwicklungsprojekte.", whenRequiredEn: "Required for all development projects.", sources: ["ISO 27001:2022 A.8.24", "BSI IT-Grundschutz CON.8", "OWASP SAMM"] },
    { id: "p47-c08", title: "Penetrationstests", titleEn: "Penetration Testing", description: "Anwendungen müssen vor dem ersten produktiven Einsatz und danach regelmäßig (mindestens jährlich) Penetrationstests unterzogen werden. Tests müssen von qualifizierten internen oder externen Testern durchgeführt werden. Identifizierte Schwachstellen müssen gemäß Schweregrad priorisiert und zeitnah behoben werden.", descriptionEn: "Applications must undergo penetration testing before initial production deployment and regularly thereafter (at least annually). Tests must be conducted by qualified internal or external testers. Identified vulnerabilities must be prioritised by severity and remediated promptly.", reason: "Penetrationstests decken Schwachstellen auf, die automatisierte Tests übersehen. Sie simulieren reale Angriffsszenarien.", reasonEn: "Penetration tests uncover vulnerabilities that automated tests miss. They simulate real attack scenarios.", whenRequired: "Erforderlich vor Go-Live und mindestens jährlich.", whenRequiredEn: "Required before go-live and at least annually.", sources: ["ISO 27001:2022 A.8.29", "NIS2 Art.21(2)(e)", "BSI IT-Grundschutz CON.8"] },
    { id: "p47-c09", title: "Container- und Microservice-Sicherheit", titleEn: "Container & Microservice Security", description: "Container-Images müssen aus vertrauenswürdigen Registries stammen und regelmäßig auf Schwachstellen gescannt werden. Container müssen mit minimalen Berechtigungen laufen. Kubernetes-Cluster müssen gehärtet werden.", descriptionEn: "Container images must come from trusted registries and be regularly scanned. Containers must run with minimal permissions. Kubernetes clusters must be hardened.", reason: "Container-Umgebungen führen neue Angriffsvektoren ein.", reasonEn: "Container environments introduce new attack vectors.", whenRequired: "Erforderlich für containerisierte Anwendungen.", whenRequiredEn: "Required for containerised applications.", sources: ["ISO 27001:2022 A.8.25", "BSI IT-Grundschutz SYS.1.6", "CIS Kubernetes Benchmark"] },
    { id: "p47-c10", title: "API-Sicherheit", titleEn: "API Security", description: "APIs müssen durch Authentifizierung (OAuth 2.0), Rate Limiting, Input-Validierung und Output-Encoding geschützt werden. API-Gateways müssen zentrale Sicherheitskontrolle bereitstellen.", descriptionEn: "APIs must be protected through authentication (OAuth 2.0), rate limiting, input validation, and output encoding. API gateways must provide centralised security control.", reason: "APIs sind ein primärer Angriffsvektor in modernen Architekturen.", reasonEn: "APIs are a primary attack vector in modern architectures.", whenRequired: "Erforderlich für API-basierte Anwendungen.", whenRequiredEn: "Required for API-based applications.", sources: ["ISO 27001:2022 A.8.25", "OWASP API Security Top 10", "BSI IT-Grundschutz APP.3.1"] },
    { id: "p47-c11", title: "Infrastructure-as-Code-Sicherheit (Canonical)", titleEn: "Infrastructure-as-Code Security (Canonical)", description: "IaC-Templates müssen Sicherheitsprüfungen unterzogen werden. Terraform und CloudFormation müssen auf Fehlkonfigurationen gescannt werden. Drift-Detection muss Abweichungen erkennen. IaC-Änderungen müssen denselben Änderungsmanagement-Prinzipien folgen wie manuelle Änderungen: Code-Review, automatisierte Tests (Terraform Plan, Policy-as-Code), Versionierung, Genehmigung und Audit-Trail. Für den Change-Management-Prozess für IaC siehe p48.", descriptionEn: "IaC templates must undergo security checks. Terraform and CloudFormation must be scanned for misconfigurations. Drift detection must identify deviations. IaC changes must follow the same change management principles as manual changes: code review, automated tests (Terraform Plan, Policy-as-Code), versioning, approval, and audit trail. For the change management process for IaC see p48.", reason: "Fehlkonfigurierte Infrastruktur ist eine Hauptursache für Cloud-Sicherheitsvorfälle. IaC-Änderungen können in Sekunden große Infrastrukturteile verändern.", reasonEn: "Misconfigured infrastructure is a leading cause of cloud security incidents. IaC changes can modify large infrastructure portions in seconds.", whenRequired: "Erforderlich für IaC-verwaltete Umgebungen.", whenRequiredEn: "Required for IaC-managed environments.", sources: ["ISO 27001:2022 A.8.25", "BSI IT-Grundschutz OPS.1.1.3", "CIS Benchmarks", "NIST CSF 2.0 PR.DS"] },
    { id: "p47-c12", title: "Sichere CI/CD-Pipeline (Canonical)", titleEn: "Secure CI/CD Pipeline (Canonical)", description: "CI/CD-Pipelines müssen als kritische Infrastruktur geschützt und gehärtet werden: Pipeline-as-Code, signierte Artefakte, isolierte Build-Umgebungen, Least-Privilege für Pipeline-Accounts, Schutz vor Pipeline-Poisoning. Pipeline-Konfigurationen müssen versioniert, Zugriffsrechte beschränkt und Secrets sicher verwaltet werden. Automatisierte Sicherheitsscans müssen in die Pipeline integriert sein. Pipeline-Manipulation muss erkannt und alarmiert werden.", descriptionEn: "CI/CD pipelines must be protected as critical infrastructure and hardened: pipeline-as-code, signed artefacts, isolated build environments, least privilege for pipeline accounts, pipeline poisoning protection. Pipeline configurations must be versioned, access rights restricted, and secrets securely managed. Automated security scans must be integrated. Pipeline manipulation must be detected and alerted.", reason: "Kompromittierte Pipelines ermöglichen Supply-Chain-Angriffe auf die gesamte Softwareauslieferung und bösartigen Code in der Produktion.", reasonEn: "Compromised pipelines enable supply chain attacks on the entire software delivery and malicious code in production.", whenRequired: "Erforderlich für alle automatisierten Deployment-Prozesse.", whenRequiredEn: "Required for automated deployments.", sources: ["ISO 27001:2022 A.8.25, A.8.31", "NIST CSF 2.0 PR.DS", "SLSA Framework", "OWASP CI/CD Security"] },
    { id: "p47-c13", title: "Threat Modelling", titleEn: "Threat Modelling", description: "Für neue Anwendungen muss ein Threat Model (STRIDE) erstellt werden. Identifizierte Bedrohungen müssen bewertet und Gegenmaßnahmen implementiert werden. Updates bei Architekturänderungen.", descriptionEn: "A threat model (STRIDE) must be created for new applications. Identified threats must be assessed and countermeasures implemented. Updates upon architecture changes.", reason: "Threat Modelling identifiziert Risiken systematisch in der Designphase.", reasonEn: "Threat modelling systematically identifies risks in the design phase.", whenRequired: "Erforderlich für neue Anwendungen.", whenRequiredEn: "Required for new applications.", sources: ["ISO 27001:2022 A.8.25", "BSI IT-Grundschutz CON.8", "OWASP Threat Modelling"] },
    { id: "p47-c14", title: "Sichere Datenbankentwicklung", titleEn: "Secure Database Development", description: "Datenbanken müssen sicher entwickelt werden: Parametrisierte Abfragen, Least-Privilege-Accounts, Verschlüsselung sensibler Felder, Audit-Logging für Datenänderungen.", descriptionEn: "Databases must be securely developed: parameterised queries, least-privilege accounts, encryption of sensitive fields, audit logging for data changes.", reason: "SQL-Injection bleibt eine der häufigsten Schwachstellenklassen.", reasonEn: "SQL injection remains one of the most common vulnerability classes.", whenRequired: "Erforderlich für datenbankgestützte Anwendungen.", whenRequiredEn: "Required for database-backed applications.", sources: ["ISO 27001:2022 A.8.25", "OWASP Top 10", "BSI IT-Grundschutz APP.4.3"] },
    { id: "p47-c15", title: "Fehlerbehandlung und Informationsleck-Prävention", titleEn: "Error Handling & Information Leak Prevention", description: "Fehlerbehandlung muss interne Details verbergen. Stack Traces und DB-Fehler nicht in Produktion anzeigen. Generische Meldungen für Benutzer, Details nur in Logs.", descriptionEn: "Error handling must hide internal details. Stack traces and DB errors must not be shown in production. Generic messages for users, details only in logs.", reason: "Detaillierte Fehlermeldungen geben Angreifern wertvolle Informationen.", reasonEn: "Detailed error messages give attackers valuable information.", whenRequired: "Erforderlich für produktive Anwendungen.", whenRequiredEn: "Required for production applications.", sources: ["ISO 27001:2022 A.8.28", "OWASP Top 10", "BSI IT-Grundschutz CON.8"] },
    { id: "p47-c16", title: "Mobile Application Security", titleEn: "Mobile Application Security", description: "Mobile Anwendungen müssen spezifisch getestet werden: lokale Datenspeicherung, API-Sicherheit, Reverse-Engineering-Schutz, Zertifikat-Pinning. OWASP Mobile Top 10 berücksichtigen.", descriptionEn: "Mobile applications must undergo specific testing: local data storage, API security, reverse engineering protection, certificate pinning. OWASP Mobile Top 10 must be addressed.", reason: "Mobile Apps haben einzigartige Sicherheitsherausforderungen.", reasonEn: "Mobile apps have unique security challenges.", whenRequired: "Erforderlich für mobile Anwendungen.", whenRequiredEn: "Required for mobile applications.", sources: ["ISO 27001:2022 A.8.25", "OWASP Mobile Top 10", "BSI TR-03161"] },
    { id: "p47-c17", title: "Überprüfung der Entwicklungsrichtlinie", titleEn: "Review of Development Policy", description: "Diese Richtlinie muss mindestens jährlich überprüft und aktualisiert werden. Neue Bedrohungen, Technologien und Best Practices müssen berücksichtigt werden. Sicherheitsschulungen für Entwickler werden zentral über p44 (Training & Awareness) geregelt. Anwendungslogging-Standards werden in p27 (Logging-Richtlinie) definiert. Authentifizierungs-Implementierungsdetails werden in p11 (Identitäts- und Authentifizierungsrichtlinie) verwaltet.", descriptionEn: "This policy must be reviewed and updated at least annually. New threats, technologies, and best practices must be considered. Security training for developers is centrally governed by p44 (Training & Awareness). Application logging standards are defined in p27 (Logging Policy). Authentication implementation details are managed in p11 (Identity & Authentication Policy).", reason: "Entwicklungstechnologien und Bedrohungen entwickeln sich ständig. Querverweis-Delegation verhindert Redundanz.", reasonEn: "Development technologies and threats are constantly evolving. Cross-reference delegation prevents redundancy.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz CON.8"] },
  ],

  /* ═══════════════════════════════════════════════════════════════
   * p48 — Change Management Policy (18 clauses)
   * Canonical owner: Release management (c13), change governance
   * Delegates: CI/CD security → p47-c12, IaC security → p47-c11, CM training → p44, Patch ops → p22
   * ═══════════════════════════════════════════════════════════════ */
  p48: [
    { id: "p48-c00", title: "Zweck und Geltungsbereich des Änderungsmanagements", titleEn: "Purpose & Scope of Change Management", description: "Diese Richtlinie definiert den kontrollierten Prozess für alle Änderungen an IT-Systemen, Anwendungen, Konfigurationen und Infrastruktur der Organisation. Sie stellt sicher, dass Änderungen keine unbeabsichtigten Ausfälle oder Sicherheitslücken verursachen. CI/CD-Pipeline-Härtung und IaC-Sicherheitsscanning werden in p47 (Sichere Entwicklung) als kanonische Quelle geregelt.", descriptionEn: "This policy defines the controlled process for all changes to IT systems, applications, configurations, and infrastructure. It ensures changes do not cause unintended outages or security gaps. CI/CD pipeline hardening and IaC security scanning are governed by p47 (Secure Development) as canonical source.", reason: "Unkontrollierte Änderungen sind eine der häufigsten Ursachen für Systemausfälle und Sicherheitsvorfälle.", reasonEn: "Uncontrolled changes are one of the most common causes of system outages and security incidents.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "NIS2 Art.21(2)(e)", "NIST CSF 2.0 PR.DS"] },
    { id: "p48-c01", title: "Änderungsklassifizierung", titleEn: "Change Classification", description: "Änderungen müssen nach Risiko und Umfang klassifiziert werden: Standard (vordefiniert, gering Risiko, vorab genehmigt), Normal (planmäßig, Genehmigung durch Change Advisory Board), Notfall (dringend, beschleunigte Genehmigung mit nachträglicher Dokumentation). Für jede Klasse müssen Genehmigungsverfahren, Testanforderungen und Dokumentation definiert sein.", descriptionEn: "Changes must be classified by risk and scope: Standard (pre-defined, low risk, pre-approved), Normal (planned, Change Advisory Board approval), Emergency (urgent, expedited approval with retrospective documentation). For each class, approval procedures, testing requirements, and documentation must be defined.", reason: "Einheitliche Behandlung aller Änderungen ist ineffizient. Klassifizierung ermöglicht risikogerechte Prozesse.", reasonEn: "Uniform treatment of all changes is inefficient. Classification enables risk-appropriate processes.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "ITIL 4"] },
    { id: "p48-c02", title: "Change Advisory Board (CAB)", titleEn: "Change Advisory Board (CAB)", description: "Ein Change Advisory Board muss alle normalen und risikoreichen Änderungen vor der Implementierung genehmigen. Das CAB muss Vertreter aus IT, Sicherheit, betroffenen Fachbereichen und ggf. Datenschutz umfassen. Entscheidungen müssen dokumentiert und nachvollziehbar sein.", descriptionEn: "A Change Advisory Board must approve all normal and high-risk changes before implementation. The CAB must include representatives from IT, security, affected departments, and data protection where applicable. Decisions must be documented and traceable.", reason: "Ohne unabhängige Prüfung können Änderungen unbemerkt Sicherheitslücken oder Ausfälle verursachen.", reasonEn: "Without independent review, changes can unnoticeably cause security gaps or outages.", whenRequired: "Erforderlich für normale und risikoreiche Änderungen.", whenRequiredEn: "Required for normal and high-risk changes.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "ITIL 4"] },
    { id: "p48-c03", title: "Test- und Validierungsanforderungen", titleEn: "Testing & Validation Requirements", description: "Alle Änderungen müssen vor der Produktivsetzung in einer separaten Testumgebung getestet werden. Tests müssen Funktionalität, Sicherheit, Performance und Rückwärtskompatibilität umfassen. Testergebnisse müssen dokumentiert und bei der Genehmigung berücksichtigt werden.", descriptionEn: "All changes must be tested in a separate test environment before production deployment. Tests must cover functionality, security, performance, and backward compatibility. Test results must be documented and considered in approval.", reason: "Ungetestete Änderungen sind ein hohes Risiko für Ausfälle und Sicherheitslücken.", reasonEn: "Untested changes are a high risk for outages and security gaps.", whenRequired: "Erforderlich für alle Änderungen.", whenRequiredEn: "Required for all changes.", sources: ["ISO 27001:2022 A.8.29, A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
    { id: "p48-c04", title: "Rollback-Verfahren", titleEn: "Rollback Procedures", description: "Für jede Änderung muss ein Rollback-Verfahren definiert sein, das die Rückkehr zum vorherigen Zustand ermöglicht. Rollback-Kriterien müssen vor der Implementierung festgelegt werden. Backups müssen vor jeder Änderung erstellt werden. Das Rollback-Verfahren muss getestet und dokumentiert sein.", descriptionEn: "A rollback procedure must be defined for every change enabling return to the previous state. Rollback criteria must be established before implementation. Backups must be created before every change. The rollback procedure must be tested and documented.", reason: "Ohne Rollback-Möglichkeit können fehlgeschlagene Änderungen zu langanhaltenden Ausfällen führen.", reasonEn: "Without rollback capability, failed changes can lead to prolonged outages.", whenRequired: "Erforderlich für alle Änderungen.", whenRequiredEn: "Required for all changes.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
    { id: "p48-c05", title: "Notfalländerungen", titleEn: "Emergency Changes", description: "Für dringende Änderungen zur Behebung kritischer Störungen oder Sicherheitslücken muss ein beschleunigtes Verfahren definiert sein. Notfalländerungen müssen von einem autorisierten Manager genehmigt werden. Die vollständige Dokumentation muss innerhalb von 48 Stunden nachgereicht werden. Notfalländerungen müssen im nächsten CAB-Meeting nachträglich überprüft werden.", descriptionEn: "An expedited procedure must be defined for urgent changes to fix critical disruptions or security gaps. Emergency changes must be approved by an authorised manager. Complete documentation must be submitted within 48 hours. Emergency changes must be retrospectively reviewed in the next CAB meeting.", reason: "Ohne Notfallverfahren werden entweder notwendige Änderungen verzögert oder reguläre Prozesse umgangen.", reasonEn: "Without emergency procedures, either necessary changes are delayed or regular processes are bypassed.", whenRequired: "Erforderlich für alle Notfallsituationen.", whenRequiredEn: "Required for all emergency situations.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "ITIL 4"] },
    { id: "p48-c06", title: "Dokumentation und Audit-Trail", titleEn: "Documentation & Audit Trail", description: "Alle Änderungen müssen vollständig dokumentiert werden: Beschreibung, Begründung, Risikoanalyse, Genehmigung, Testergebnisse, Implementierungsschritte, Rollback-Plan und Verantwortliche. Ein lückenloser Audit-Trail muss für alle Änderungen verfügbar sein.", descriptionEn: "All changes must be fully documented: description, justification, risk analysis, approval, test results, implementation steps, rollback plan, and responsible parties. A complete audit trail must be available for all changes.", reason: "Ohne Dokumentation sind Änderungen nicht nachvollziehbar und Probleme nicht auf ihre Ursache zurückzuführen.", reasonEn: "Without documentation, changes are not traceable and problems cannot be traced to their cause.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
    { id: "p48-c07", title: "Change-Freeze-Perioden", titleEn: "Change Freeze Periods", description: "Wir müssen Change-Freeze-Perioden definieren, in denen keine nicht-kritischen Änderungen durchgeführt werden dürfen (z.B. Jahresabschluss, Hochlastzeiten, Feiertage). Ausnahmen bedürfen der Genehmigung durch die Geschäftsleitung. Die Termine müssen im Voraus geplant und kommuniziert werden.", descriptionEn: "We must define change freeze periods during which no non-critical changes may be made (e.g., year-end closing, peak load times, holidays). Exceptions require executive management approval. Dates must be planned and communicated in advance.", reason: "Änderungen während kritischer Geschäftszeiten erhöhen das Risiko geschäftskritischer Ausfälle.", reasonEn: "Changes during critical business periods increase the risk of business-critical outages.", whenRequired: "Empfohlen für alle Organisationen.", whenRequiredEn: "Recommended for all organisations.", sources: ["ISO 27001:2022 A.8.32", "ITIL 4", "BSI IT-Grundschutz OPS.1.1.3"] },
    { id: "p48-c08", title: "Konfigurationsmanagement", titleEn: "Configuration Management", description: "Alle IT-Systeme müssen in einer Configuration Management Database (CMDB) erfasst sein. Änderungen an Konfigurationen müssen dem Änderungsmanagement-Prozess folgen. Konfigurationsbaselines müssen definiert und versioniert werden. Abweichungen von der Baseline müssen automatisch erkannt werden.", descriptionEn: "All IT systems must be recorded in a Configuration Management Database (CMDB). Configuration changes must follow the change management process. Configuration baselines must be defined and versioned. Deviations from baseline must be automatically detected.", reason: "Ohne CMDB ist die Auswirkungsanalyse von Änderungen unvollständig und Konfigurationsdrift bleibt unentdeckt.", reasonEn: "Without CMDB, change impact analysis is incomplete and configuration drift remains undetected.", whenRequired: "Erforderlich für alle IT-Systeme.", whenRequiredEn: "Required for all IT systems.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz OPS.1.1.3", "ITIL 4"] },
    { id: "p48-c09", title: "Impact-Analyse vor Änderungen", titleEn: "Impact Analysis Before Changes", description: "Vor jeder Änderung muss eine Impact-Analyse durchgeführt werden: betroffene Systeme und Dienste, potenzielle Ausfallrisiken, betroffene Benutzer, Abhängigkeiten zu anderen Systemen und Sicherheitsimplikationen. Die CMDB muss als Grundlage für die Analyse genutzt werden.", descriptionEn: "Before every change, an impact analysis must be conducted: affected systems and services, potential outage risks, affected users, dependencies to other systems, and security implications. The CMDB must be used as the basis for analysis.", reason: "Ohne Impact-Analyse können unerwartete Nebenwirkungen von Änderungen auftreten.", reasonEn: "Without impact analysis, unexpected side effects of changes can occur.", whenRequired: "Erforderlich für alle normalen und risikoreichen Änderungen.", whenRequiredEn: "Required for all normal and high-risk changes.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "ITIL 4"] },
    { id: "p48-c10", title: "Sicherheitsrelevante Änderungen", titleEn: "Security-Relevant Changes", description: "Änderungen mit Sicherheitsrelevanz (Firewall-Regeln, Zugriffskontrollen, Verschlüsselungskonfigurationen, Netzwerksegmentierung) müssen vom ISB/CISO genehmigt werden. Sicherheitstests müssen vor und nach der Implementierung durchgeführt werden. Die Dokumentation muss die Sicherheitsimplikationen explizit beschreiben.", descriptionEn: "Security-relevant changes (firewall rules, access controls, encryption configurations, network segmentation) must be approved by the CISO. Security tests must be conducted before and after implementation. Documentation must explicitly describe security implications.", reason: "Sicherheitsrelevante Änderungen können die Schutzwirkung des gesamten Sicherheitskonzepts beeinträchtigen.", reasonEn: "Security-relevant changes can compromise the effectiveness of the entire security concept.", whenRequired: "Erforderlich für alle sicherheitsrelevanten Änderungen.", whenRequiredEn: "Required for all security-relevant changes.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "NIST CSF 2.0 PR.DS"] },
    { id: "p48-c11", title: "Wartungsfenster und Kommunikation", titleEn: "Maintenance Windows & Communication", description: "Geplante Änderungen mit potenziellem Einfluss auf die Verfügbarkeit müssen in definierten Wartungsfenstern durchgeführt werden. Betroffene Nutzer und Stakeholder müssen vorab informiert werden. Nach Abschluss muss eine Statusmeldung erfolgen. Ungeplante Wartungen müssen minimiert und nach dem Notfalländerungsprozess durchgeführt werden.", descriptionEn: "Planned changes with potential availability impact must be conducted during defined maintenance windows. Affected users and stakeholders must be informed in advance. A status notification must follow completion. Unplanned maintenance must be minimised and follow the emergency change process.", reason: "Unangekündigte Änderungen mit Ausfallwirkung beeinträchtigen das Vertrauen und die Arbeitsproduktivität.", reasonEn: "Unannounced changes with outage impact impair trust and work productivity.", whenRequired: "Erforderlich für alle Änderungen mit Verfügbarkeitsauswirkung.", whenRequiredEn: "Required for all changes with availability impact.", sources: ["ISO 27001:2022 A.8.32", "ITIL 4"] },
    { id: "p48-c12", title: "Datenbankänderungen und Schema-Migrationen", titleEn: "Database Changes & Schema Migrations", description: "Datenbankänderungen (Schema-Änderungen, Migrationen, Index-Änderungen) müssen als risikoreiche Änderungen behandelt werden. Backup vor der Änderung ist Pflicht. Rollback-Skripte müssen vorbereitet sein. Performance-Tests müssen vor der Produktivsetzung durchgeführt werden. Änderungen müssen versioniert und nachvollziehbar sein.", descriptionEn: "Database changes (schema changes, migrations, index changes) must be treated as high-risk changes. Backup before the change is mandatory. Rollback scripts must be prepared. Performance tests must be conducted before production deployment. Changes must be versioned and traceable.", reason: "Fehlerhafte Datenbankänderungen können zu Datenverlust und langanhaltenden Ausfällen führen.", reasonEn: "Faulty database changes can lead to data loss and prolonged outages.", whenRequired: "Erforderlich für alle Datenbankänderungen.", whenRequiredEn: "Required for all database changes.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz APP.4.3"] },
    { id: "p48-c13", title: "Release-Management (Canonical)", titleEn: "Release Management (Canonical)", description: "Releases müssen geplant, koordiniert und kontrolliert in die Produktion überführt werden. Release-Pakete müssen vollständig getestet, dokumentiert und genehmigt sein. Release-Kalender müssen geführt werden. Post-Implementation-Reviews müssen nach jedem größeren Release durchgeführt werden. Staging, Smoke-Tests, Blue-Green/Canary Deployments, automatische Rollbacks und Post-Deployment-Monitoring sind erforderlich. Artefakte müssen signiert werden.", descriptionEn: "Releases must be planned, coordinated, and controlled when deployed to production. Release packages must be fully tested, documented, and approved. Release calendars must be maintained. Post-implementation reviews must be conducted after every major release. Staging, smoke tests, blue-green/canary deployments, automatic rollbacks, and post-deployment monitoring are required. Artefacts must be signed.", reason: "Unkontrollierte Releases führen zu Instabilität und Sicherheitslücken in der Produktion.", reasonEn: "Uncontrolled releases lead to instability and security gaps in production.", whenRequired: "Erforderlich für alle Software-Releases.", whenRequiredEn: "Required for all software releases.", sources: ["ISO 27001:2022 A.8.31, A.8.32", "ITIL 4", "BSI IT-Grundschutz OPS.1.1.3", "NIS2 Art.21(2)(e)", "NIST CSF 2.0 PR.DS"] },
    { id: "p48-c14", title: "Netzwerkänderungen", titleEn: "Network Changes", description: "Netzwerkänderungen (Firewall-Regeln, Routing, VLAN-Konfiguration, DNS) müssen besonders sorgfältig geplant und getestet werden. Netzwerkdiagramme müssen nach jeder Änderung aktualisiert werden. Die Auswirkung auf Sicherheitszonen und Segmentierung muss bewertet werden. Der ISB/CISO muss Netzwerkänderungen genehmigen.", descriptionEn: "Network changes (firewall rules, routing, VLAN configuration, DNS) must be particularly carefully planned and tested. Network diagrams must be updated after every change. Impact on security zones and segmentation must be assessed. CISO must approve network changes.", reason: "Netzwerkänderungen können die gesamte Sicherheitsarchitektur beeinflussen und Kommunikation unterbrechen.", reasonEn: "Network changes can affect the entire security architecture and disrupt communication.", whenRequired: "Erforderlich für alle Netzwerkänderungen.", whenRequiredEn: "Required for all network changes.", sources: ["ISO 27001:2022 A.8.20-8.22", "BSI IT-Grundschutz NET.1.1", "NIST CSF 2.0 PR.DS"] },
    { id: "p48-c15", title: "Change-Management-KPIs und Überprüfung", titleEn: "Change Management KPIs & Review", description: "Die Wirksamkeit des Änderungsmanagements muss durch KPIs gemessen werden: Erfolgsquote von Änderungen, Notfalländerungsanteil, Rollback-Häufigkeit, durchschnittliche Genehmigungsdauer, Anzahl durch Änderungen verursachter Vorfälle und Change-Backlog-Größe. Das Änderungsmanagement-Verfahren muss mindestens jährlich überprüft werden. Die Analyse muss fehlgeschlagene Änderungen und Prozesseffizienz bewerten.", descriptionEn: "Change management effectiveness must be measured through KPIs: change success rate, emergency change proportion, rollback frequency, average approval duration, change-caused incidents, and change backlog size. The change management process must be reviewed at least annually. Analysis must evaluate failed changes and process efficiency.", reason: "Ohne messbare KPIs kann die Wirksamkeit des Änderungsmanagements nicht objektiv bewertet und verbessert werden.", reasonEn: "Without measurable KPIs, change management effectiveness cannot be objectively assessed and improved.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1, §10.1-10.2", "ITIL 4", "BSI IT-Grundschutz ISMS.1"] },
    { id: "p48-c16", title: "Post-Implementation-Review", titleEn: "Post-Implementation Review", description: "Nach jeder bedeutenden Änderung muss ein Post-Implementation-Review durchgeführt werden: Wurde das Ziel erreicht? Gab es unerwartete Probleme? War der Prozess effizient? Welche Lessons Learned gibt es? Bei fehlgeschlagenen Änderungen muss eine Root-Cause-Analyse durchgeführt werden. Schulungen zum Änderungsmanagement werden zentral über p44 (Training & Awareness) geregelt. Operative Patch-Management-Details werden in p22 (Patch-Management-Richtlinie) verwaltet.", descriptionEn: "After every significant change, a post-implementation review must be conducted: Was the objective achieved? Were there unexpected problems? Was the process efficient? What lessons learned exist? For failed changes, a root cause analysis must be conducted. Change management training is centrally governed by p44 (Training & Awareness). Operational patch management details are managed in p22 (Patch Management Policy).", reason: "Ohne Post-Implementation-Review werden Fehler wiederholt und der Prozess nicht verbessert. Querverweis-Delegation verhindert Redundanz.", reasonEn: "Without post-implementation review, mistakes are repeated and the process is not improved. Cross-reference delegation prevents redundancy.", whenRequired: "Erforderlich für alle bedeutenden Änderungen.", whenRequiredEn: "Required for all significant changes.", sources: ["ISO 27001:2022 §10.1", "ITIL 4", "BSI IT-Grundschutz OPS.1.1.3"] },
  ],

  /* ═══════════════════════════════════════════════════════════════
   * p49 — Physical Security Policy (20 clauses)
   * Delegates: Secure disposal → p24, Secure meeting rooms → p25
   * ═══════════════════════════════════════════════════════════════ */
  p49: [
    { id: "p49-c00", title: "Zweck und Geltungsbereich der physischen Sicherheitsrichtlinie", titleEn: "Purpose & Scope of Physical Security Policy", description: "Diese Richtlinie definiert die Anforderungen an den physischen Schutz von Gebäuden, Räumlichkeiten und IT-Infrastruktur der Organisation. Sie umfasst Zutrittskontrolle, Umgebungsüberwachung, Schutz vor Naturkatastrophen und Schutz von Versorgungseinrichtungen. Sichere Entsorgung von Geräten und Datenträgern wird in p24 (Medien- und Datenträgerrichtlinie) geregelt. Verhaltensregeln für sichere Besprechungsräume werden in p25 (Clean-Desk-Richtlinie) verwaltet.", descriptionEn: "This policy defines requirements for physical protection of buildings, premises, and IT infrastructure. It covers access control, environmental monitoring, protection from natural disasters, and protection of utilities. Secure disposal of equipment and media is governed by p24 (Media & Storage Policy). Behavioural rules for secure meeting rooms are managed in p25 (Clean Desk Policy).", reason: "Physische Sicherheit ist die Grundlage aller IT-Sicherheit. Ohne physischen Schutz sind alle logischen Schutzmaßnahmen wirkungslos.", reasonEn: "Physical security is the foundation of all IT security. Without physical protection, all logical measures are ineffective.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.1-7.14", "BSI IT-Grundschutz INF.1-2", "NIS2 Art.21(2)(i)", "NIST CSF 2.0 PR.IR"] },
    { id: "p49-c01", title: "Sicherheitszonen und Perimeterschutz", titleEn: "Security Zones & Perimeter Protection", description: "Wir müssen Sicherheitszonen definieren: öffentlicher Bereich (Empfang), kontrollierter Bereich (Büros), eingeschränkter Bereich (Serverräume, Rechenzentren) und hochsicherer Bereich (tresorgeschützte Bereiche). Jede Zone muss angemessene Zutrittskontrolle und Überwachung haben. Der Gebäudeperimeter muss gesichert sein.", descriptionEn: "We must define security zones: public area (reception), controlled area (offices), restricted area (server rooms, data centres), and high-security area (vault-protected areas). Each zone must have appropriate access control and monitoring. The building perimeter must be secured.", reason: "Zonenbasierte Sicherheit ermöglicht abgestufte Schutzmaßnahmen entsprechend der Sensitivität der in jedem Bereich befindlichen Assets.", reasonEn: "Zone-based security enables graduated protective measures according to the sensitivity of assets in each area.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.1-7.2", "BSI IT-Grundschutz INF.1", "NIST CSF 2.0 PR.IR"] },
    { id: "p49-c02", title: "Zutrittskontrollsysteme", titleEn: "Access Control Systems", description: "Zutrittskontrollsysteme müssen für alle eingeschränkten Bereiche implementiert sein: elektronische Zugangskarten, biometrische Systeme für hochsichere Bereiche, Protokollierung aller Zutritte und Alarmsysteme bei unbefugtem Zutritt. Besucher müssen registriert und begleitet werden. Zutrittsberechtigungen müssen regelmäßig überprüft werden.", descriptionEn: "Access control systems must be implemented for all restricted areas: electronic access cards, biometric systems for high-security areas, logging of all entries, and alarm systems for unauthorised access. Visitors must be registered and escorted. Access permissions must be regularly reviewed.", reason: "Unkontrollierter physischer Zugang ermöglicht Diebstahl, Sabotage und Manipulation von IT-Systemen.", reasonEn: "Uncontrolled physical access enables theft, sabotage, and manipulation of IT systems.", whenRequired: "Erforderlich für alle eingeschränkten Bereiche.", whenRequiredEn: "Required for all restricted areas.", sources: ["ISO 27001:2022 A.7.2-7.4", "BSI IT-Grundschutz INF.1", "NIST CSF 2.0 PR.AA"] },
    { id: "p49-c03", title: "Rechenzentrum und Serverraum", titleEn: "Data Centre & Server Room", description: "Rechenzentren und Serverräume müssen besonderen physischen Schutz aufweisen: redundante Stromversorgung (USV, Generator), Klimatisierung mit Überwachung, Brandschutz (Früherkennung, Gaslöschanlage), Wasserschutz, elektromagnetische Abschirmung und 24/7-Überwachung. Zutritt nur für autorisiertes Personal.", descriptionEn: "Data centres and server rooms must have special physical protection: redundant power supply (UPS, generator), air conditioning with monitoring, fire protection (early detection, gas suppression), water protection, electromagnetic shielding, and 24/7 monitoring. Access only for authorised personnel.", reason: "IT-Infrastruktur in Rechenzentren ist besonders kritisch und schützenswert. Physische Einwirkungen können zum Totalausfall führen.", reasonEn: "IT infrastructure in data centres is particularly critical. Physical impacts can lead to total failure.", whenRequired: "Erforderlich für alle Rechenzentren und Serverräume.", whenRequiredEn: "Required for all data centres and server rooms.", sources: ["ISO 27001:2022 A.7.5-7.8, A.7.11-7.12", "BSI IT-Grundschutz INF.2", "NIST CSF 2.0 PR.IR"] },
    { id: "p49-c04", title: "Umgebungsüberwachung", titleEn: "Environmental Monitoring", description: "Kritische Bereiche müssen mit Umgebungssensoren ausgestattet sein: Temperatur- und Feuchtigkeitssensoren, Wasserleckage-Detektoren, Rauchmelder und Brandmeldeanlage, Spannungsüberwachung und Erschütterungssensoren. Alarme müssen automatisch an Verantwortliche weitergeleitet werden. Schwellenwerte müssen definiert und regelmäßig überprüft werden.", descriptionEn: "Critical areas must be equipped with environmental sensors: temperature and humidity sensors, water leak detectors, smoke detectors and fire alarm systems, voltage monitoring, and vibration sensors. Alarms must be automatically forwarded to responsible persons. Thresholds must be defined and regularly reviewed.", reason: "Umgebungseinflüsse (Hitze, Feuchtigkeit, Wasser) können IT-Systeme zerstören. Frühwarnsysteme verhindern Schäden.", reasonEn: "Environmental influences (heat, humidity, water) can destroy IT systems. Early warning systems prevent damage.", whenRequired: "Erforderlich für alle Bereiche mit kritischer IT-Infrastruktur.", whenRequiredEn: "Required for all areas with critical IT infrastructure.", sources: ["ISO 27001:2022 A.7.11-7.13", "BSI IT-Grundschutz INF.2", "NIST CSF 2.0 PR.IR"] },
    { id: "p49-c05", title: "Versorgungssicherheit", titleEn: "Utility Security", description: "Die Versorgung mit Strom, Kühlung und Netzwerk muss redundant ausgelegt sein. USV-Anlagen müssen mindestens 30 Minuten Überbrückung bieten. Notstromgeneratoren müssen für kritische Systeme verfügbar sein. Wartungsverträge für alle Versorgungseinrichtungen müssen abgeschlossen sein. Regelmäßige Tests der Notversorgung müssen durchgeführt werden.", descriptionEn: "Power, cooling, and network supply must be designed redundantly. UPS systems must provide at least 30 minutes bridge time. Emergency generators must be available for critical systems. Maintenance contracts for all utility equipment must be in place. Regular testing of emergency supply must be conducted.", reason: "Versorgungsausfälle (Strom, Kühlung) können IT-Systeme beschädigen und zu Datenverlust führen.", reasonEn: "Utility failures (power, cooling) can damage IT systems and lead to data loss.", whenRequired: "Erforderlich für alle kritischen IT-Standorte.", whenRequiredEn: "Required for all critical IT locations.", sources: ["ISO 27001:2022 A.7.11", "BSI IT-Grundschutz INF.2", "NIST CSF 2.0 PR.IR"] },
    { id: "p49-c06", title: "Besuchermanagement", titleEn: "Visitor Management", description: "Besucher müssen sich am Empfang registrieren und einen sichtbaren Besucherausweis tragen. Besucher dürfen eingeschränkte Bereiche nur in Begleitung betreten. Besucherprotokolle müssen geführt und aufbewahrt werden. Zugangsmedien müssen bei Verlassen zurückgegeben werden.", descriptionEn: "Visitors must register at reception and wear a visible visitor badge. Visitors may only enter restricted areas when escorted. Visitor logs must be maintained. Access media must be returned upon leaving.", reason: "Unkontrollierter Besucherzugang ermöglicht Social Engineering, Spionage und physische Angriffe.", reasonEn: "Uncontrolled visitor access enables social engineering, espionage, and physical attacks.", whenRequired: "Erforderlich für alle Standorte.", whenRequiredEn: "Required for all locations.", sources: ["ISO 27001:2022 A.7.2", "BSI IT-Grundschutz INF.1"] },
    { id: "p49-c07", title: "Videoüberwachung (CCTV)", titleEn: "Video Surveillance (CCTV)", description: "Videoüberwachung muss für Perimeter, Eingänge und kritische Bereiche implementiert sein. Aufzeichnungen müssen mindestens 30 Tage aufbewahrt werden. Datenschutzanforderungen (Beschilderung, DSFA, Löschfristen) müssen eingehalten werden. Der Zugriff auf Aufzeichnungen muss auf autorisiertes Personal beschränkt sein.", descriptionEn: "Video surveillance must be implemented for perimeter, entrances, and critical areas. Recordings must be retained for at least 30 days. Data protection requirements (signage, DPIA, deletion deadlines) must be met. Access to recordings must be restricted to authorised personnel.", reason: "Videoüberwachung dient der Abschreckung, Erkennung und forensischen Aufklärung von Sicherheitsvorfällen.", reasonEn: "Video surveillance serves deterrence, detection, and forensic investigation of security incidents.", whenRequired: "Empfohlen für alle Standorte mit kritischer Infrastruktur.", whenRequiredEn: "Recommended for all locations with critical infrastructure.", sources: ["ISO 27001:2022 A.7.4", "DSGVO Art.6, Art.35", "BSI IT-Grundschutz INF.1"] },
    { id: "p49-c08", title: "Brandschutz", titleEn: "Fire Protection", description: "Brandschutzmaßnahmen müssen implementiert sein: Brandmeldeanlage mit Aufschaltung zur Feuerwehr, Gaslöschanlagen in Serverräumen, Feuerlöscher, Brandschutztüren, Fluchtwege und regelmäßige Brandschutzübungen. Brandlasten in IT-Bereichen müssen minimiert werden.", descriptionEn: "Fire protection measures must be implemented: fire alarm system connected to fire department, gas suppression in server rooms, fire extinguishers, fire doors, escape routes, and regular fire drills. Fire loads in IT areas must be minimised.", reason: "Brände können IT-Infrastruktur vollständig zerstören und den Geschäftsbetrieb langfristig lahmlegen.", reasonEn: "Fires can completely destroy IT infrastructure and paralyse business operations long-term.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.7.5", "BSI IT-Grundschutz INF.1-2"] },
    { id: "p49-c09", title: "Schlüssel- und Zugangsmedien-Management", titleEn: "Key & Access Media Management", description: "Physische Schlüssel und Zugangsmedien (Karten, Transponder) müssen inventarisiert und kontrolliert werden. Ausgabe und Rückgabe müssen dokumentiert werden. Bei Verlust muss sofortige Sperrung und Austausch erfolgen. Master-Schlüssel müssen besonders gesichert aufbewahrt werden.", descriptionEn: "Physical keys and access media (cards, transponders) must be inventoried and controlled. Issue and return must be documented. Upon loss, immediate blocking and replacement must occur. Master keys must be stored with special security.", reason: "Unkontrollierte Schlüssel und Zugangsmedien untergraben alle physischen Sicherheitsmaßnahmen.", reasonEn: "Uncontrolled keys and access media undermine all physical security measures.", whenRequired: "Erforderlich für alle Standorte.", whenRequiredEn: "Required for all locations.", sources: ["ISO 27001:2022 A.7.2", "BSI IT-Grundschutz INF.1"] },
    { id: "p49-c10", title: "Lieferantenbereich und Anlieferzone", titleEn: "Supplier Area & Loading Zone", description: "Anlieferbereiche müssen von den Hauptarbeitsbereichen getrennt sein. Lieferungen müssen registriert und überprüft werden. Lieferanten dürfen nur den Anlieferbereich betreten. IT-Lieferungen müssen auf Manipulationssicherheit geprüft werden.", descriptionEn: "Delivery areas must be separated from main work areas. Deliveries must be registered and inspected. Suppliers may only enter the delivery area. IT deliveries must be checked for tamper resistance.", reason: "Anlieferzonen sind potenzielle Einstiegspunkte für unbefugten Zugang und Manipulation.", reasonEn: "Loading zones are potential entry points for unauthorised access and tampering.", whenRequired: "Erforderlich für alle Standorte mit Anlieferung.", whenRequiredEn: "Required for all locations with deliveries.", sources: ["ISO 27001:2022 A.7.3", "BSI IT-Grundschutz INF.1"] },
    { id: "p49-c11", title: "Kabelschutz und Infrastruktursicherheit", titleEn: "Cabling Protection & Infrastructure Security", description: "Strom- und Datenkabel müssen gegen unbefugten Zugriff, Beschädigung und Abhören geschützt sein. Kabel in öffentlichen Bereichen müssen in gesicherten Kanälen verlegt werden. Glasfaser ist für sensible Verbindungen zu bevorzugen. Kabelschränke und Patchfelder müssen verschlossen sein.", descriptionEn: "Power and data cables must be protected against unauthorised access, damage, and interception. Cables in public areas must be routed in secured conduits. Fibre optic is preferred for sensitive connections. Cable cabinets and patch panels must be locked.", reason: "Ungeschützte Kabel ermöglichen Abhörangriffe und physische Manipulation der Netzwerkinfrastruktur.", reasonEn: "Unprotected cables enable eavesdropping attacks and physical manipulation of network infrastructure.", whenRequired: "Erforderlich für alle Standorte.", whenRequiredEn: "Required for all locations.", sources: ["ISO 27001:2022 A.7.12", "BSI IT-Grundschutz INF.4"] },
    { id: "p49-c12", title: "Naturkatastrophen- und Umgebungsrisiken", titleEn: "Natural Disaster & Environmental Risks", description: "Wir müssen Umgebungsrisiken für jeden Standort bewerten: Hochwasser, Erdbeben, Sturm, Blitzschlag, extreme Temperaturen. Schutzmaßnahmen müssen implementiert sein: Blitzschutz, Hochwasserschutz, erdbebensichere Montage für Server, Temperaturüberwachung und Notfallpläne für Evakuierung.", descriptionEn: "We must assess environmental risks for each location: flooding, earthquakes, storms, lightning, extreme temperatures. Protective measures must be implemented: lightning protection, flood protection, earthquake-resistant server mounting, temperature monitoring, and emergency evacuation plans.", reason: "Naturkatastrophen können ohne Vorwarnung eintreten und die gesamte IT-Infrastruktur zerstören.", reasonEn: "Natural disasters can occur without warning and destroy the entire IT infrastructure.", whenRequired: "Erforderlich für alle Standorte.", whenRequiredEn: "Required for all locations.", sources: ["ISO 27001:2022 A.7.5", "BSI IT-Grundschutz INF.1-2", "NIST CSF 2.0 PR.IR"] },
    { id: "p49-c13", title: "Wartung physischer Sicherheitssysteme", titleEn: "Maintenance of Physical Security Systems", description: "Alle physischen Sicherheitssysteme (Zutrittskontrolle, CCTV, Brandmeldeanlagen, USV, Klimaanlagen) müssen regelmäßig gewartet und getestet werden. Wartungsverträge müssen abgeschlossen sein. Wartungsarbeiten an Sicherheitssystemen müssen beaufsichtigt und protokolliert werden.", descriptionEn: "All physical security systems (access control, CCTV, fire alarms, UPS, air conditioning) must be regularly maintained and tested. Maintenance contracts must be in place. Maintenance work on security systems must be supervised and logged.", reason: "Nicht gewartete Sicherheitssysteme fallen im Ernstfall aus und bieten keinen Schutz.", reasonEn: "Unmaintained security systems fail in emergencies and provide no protection.", whenRequired: "Erforderlich für alle physischen Sicherheitssysteme.", whenRequiredEn: "Required for all physical security systems.", sources: ["ISO 27001:2022 A.7.13", "BSI IT-Grundschutz INF.1-2"] },
    { id: "p49-c14", title: "Mehrstufige Zutrittskontrolle für Hochsicherheitsbereiche", titleEn: "Multi-Factor Access Control for High-Security Areas", description: "Hochsicherheitsbereiche (Rechenzentren, Tresorräume) müssen mehrstufige Zutrittskontrolle implementieren: Kombination aus Karte + PIN, biometrisch + Karte oder Zweipersonenregel (Vier-Augen-Prinzip). Zutritte müssen videoüberwacht und sofort alarmiert werden bei unbefugten Versuchen.", descriptionEn: "High-security areas (data centres, vault rooms) must implement multi-factor access control: combination of card + PIN, biometric + card, or two-person rule (four-eyes principle). Entries must be video-monitored and immediately alerted upon unauthorised attempts.", reason: "Einfache Zugangskontrollen können durch Kartenverlust oder -diebstahl umgangen werden. Mehrstufige Kontrolle erhöht die Sicherheit signifikant.", reasonEn: "Simple access controls can be bypassed through card loss or theft. Multi-factor control significantly increases security.", whenRequired: "Erforderlich für alle Hochsicherheitsbereiche.", whenRequiredEn: "Required for all high-security areas.", sources: ["ISO 27001:2022 A.7.2", "BSI IT-Grundschutz INF.2"] },
    { id: "p49-c15", title: "Physische Sicherheit bei Außenstandorten", titleEn: "Physical Security at Remote Sites", description: "Außenstandorte, Filialen und Außenstellen müssen angemessene physische Sicherheitsmaßnahmen haben. Mindestanforderungen: verschlossene IT-Schränke, Zutrittskontrolle, Alarmanlage und Videoüberwachung. Regelmäßige Sicherheitsinspektionen müssen durchgeführt werden.", descriptionEn: "Remote sites, branches, and field offices must have appropriate physical security measures. Minimum requirements: locked IT cabinets, access control, alarm system, and video surveillance. Regular security inspections must be conducted.", reason: "Außenstandorte werden oft mit geringerem Sicherheitsniveau betrieben, sind aber gleichermaßen Angriffsziele.", reasonEn: "Remote sites are often operated with lower security levels but are equally attack targets.", whenRequired: "Erforderlich für alle Außenstandorte.", whenRequiredEn: "Required for all remote sites.", sources: ["ISO 27001:2022 A.7.1-7.2", "BSI IT-Grundschutz INF.1"] },
    { id: "p49-c16", title: "Physische Sicherheitsaudits", titleEn: "Physical Security Audits", description: "Physische Sicherheitsaudits müssen mindestens jährlich für alle Standorte durchgeführt werden. Audits müssen Zutrittskontrolle, Umgebungssicherheit, Verkabelung, Clean-Desk-Compliance, Besuchermanagement und Notfallausrüstung überprüfen. Feststellungen müssen priorisiert und nachverfolgt werden.", descriptionEn: "Physical security audits must be conducted at least annually for all locations. Audits must review access control, environmental security, cabling, clean desk compliance, visitor management, and emergency equipment. Findings must be prioritised and tracked.", reason: "Ohne regelmäßige Audits werden Schwachstellen in der physischen Sicherheit nicht erkannt.", reasonEn: "Without regular audits, weaknesses in physical security are not detected.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.2", "BSI IT-Grundschutz ISMS.1"] },
    { id: "p49-c17", title: "Evakuierungsplanung und -übungen", titleEn: "Evacuation Planning & Drills", description: "Evakuierungspläne müssen für alle Standorte erstellt und ausgehängt sein. Evakuierungsübungen müssen mindestens zweimal jährlich durchgeführt werden. Sammelplätze müssen definiert sein. Für mobilitätseingeschränkte Personen müssen besondere Evakuierungsverfahren vorgesehen sein. IT-Notabschaltverfahren müssen definiert sein.", descriptionEn: "Evacuation plans must be created and posted for all locations. Evacuation drills must be conducted at least twice yearly. Assembly points must be defined. Special evacuation procedures must be provided for persons with mobility restrictions. IT emergency shutdown procedures must be defined.", reason: "Bei Bränden oder anderen Gefahren hat der Personenschutz absolute Priorität. Ungeübte Evakuierungen führen zu Chaos und Gefährdung.", reasonEn: "During fires or other hazards, personnel protection has absolute priority. Unpracticed evacuations lead to chaos and endangerment.", whenRequired: "Gesetzlich vorgeschrieben.", whenRequiredEn: "Legally required.", sources: ["ArbSchG", "ASR A2.3", "BSI IT-Grundschutz INF.1"] },
    { id: "p49-c18", title: "Schutz vor Elektromagnetischer Abstrahlung", titleEn: "Protection Against Electromagnetic Emanation", description: "Für Bereiche mit streng vertraulicher Informationsverarbeitung muss der Schutz gegen kompromittierende Abstrahlung (TEMPEST) bewertet werden. Abschirmungsmaßnahmen müssen implementiert werden, wo das Risiko dies rechtfertigt. Zone-Definitionen nach BSI TL 03305 müssen berücksichtigt werden.", descriptionEn: "For areas processing strictly confidential information, protection against compromising emanation (TEMPEST) must be assessed. Shielding measures must be implemented where risk justifies it. Zone definitions per BSI TL 03305 must be considered.", reason: "Elektromagnetische Abstrahlung von IT-Geräten kann von außen abgefangen und zur Informationsgewinnung genutzt werden.", reasonEn: "Electromagnetic emanation from IT devices can be intercepted externally and used for information gathering.", whenRequired: "Erforderlich für Hochsicherheitsbereiche mit Verschlusssachen.", whenRequiredEn: "Required for high-security areas with classified information.", sources: ["BSI TL 03305", "ISO 27001:2022 A.7.5", "BSI IT-Grundschutz INF.2"] },
    { id: "p49-c19", title: "Überprüfung der physischen Sicherheitsrichtlinie", titleEn: "Review of Physical Security Policy", description: "Diese Richtlinie muss mindestens jährlich überprüft und aktualisiert werden. Physische Sicherheitsinspektionen müssen regelmäßig durchgeführt werden. Sichere Entsorgung von IT-Geräten und Datenträgern (DIN 66399, Vernichtungsprotokoll) wird kanonisch in p24 (Medien- und Datenträgerrichtlinie) geregelt. Verhaltensanforderungen für vertrauliche Besprechungsräume (Schallschutz, IoT-Verbote) werden in p25 (Clean-Desk-Richtlinie) verwaltet.", descriptionEn: "This policy must be reviewed and updated at least annually. Physical security inspections must be conducted regularly. Secure disposal of IT equipment and media (DIN 66399, destruction logs) is canonically governed in p24 (Media & Storage Policy). Behavioural requirements for confidential meeting rooms (soundproofing, IoT bans) are managed in p25 (Clean Desk Policy).", reason: "Physische Sicherheitsanforderungen ändern sich mit neuen Bedrohungen und Standortveränderungen. Querverweis-Delegation verhindert Redundanz.", reasonEn: "Physical security requirements change with new threats and location changes. Cross-reference delegation prevents redundancy.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §10.1-10.2", "BSI IT-Grundschutz INF.1"] },
  ],

  /* ═══════════════════════════════════════════════════════════════
   * p50 — AI Policy (19 clauses)
   * Consolidates: AI Incident Mgmt + Response → c17; Model Versioning + Lifecycle → c10
   * Delegates: AI training → p44, AI provider management → p42/p43
   * ═══════════════════════════════════════════════════════════════ */
  p50: [
    { id: "p50-c00", title: "Zweck und Geltungsbereich der KI-Richtlinie", titleEn: "Purpose & Scope of AI Policy", description: "Diese Richtlinie definiert die Anforderungen an den sicheren, ethischen und rechtskonformen Einsatz von KI-Systemen innerhalb der Organisation. Sie gilt für alle KI-Anwendungen, einschließlich generativer KI, maschinelles Lernen und automatisierte Entscheidungssysteme. KI-Schulungen werden zentral über p44 (Training & Awareness) geregelt. KI-Anbietermanagement folgt den Anforderungen aus p42 (Lieferantensicherheit) und p43 (Third-Party Risk Management) mit KI-spezifischen Ergänzungen.", descriptionEn: "This policy defines requirements for the secure, ethical, and legally compliant use of AI systems within the organisation. It applies to all AI applications including generative AI, machine learning, and automated decision systems. AI training is centrally governed by p44 (Training & Awareness). AI provider management follows requirements from p42 (Supplier Security) and p43 (Third-Party Risk Management) with AI-specific additions.", reason: "KI-Systeme bringen spezifische Risiken mit sich: Bias, Datenschutzverletzungen, mangelnde Transparenz und unkontrollierte Nutzung. Eine klare Richtlinie schafft den Rahmen für verantwortungsvollen KI-Einsatz.", reasonEn: "AI systems bring specific risks: bias, data protection violations, lack of transparency, and uncontrolled usage. A clear policy creates the framework for responsible AI use.", whenRequired: "Erforderlich sobald KI-Systeme eingesetzt werden.", whenRequiredEn: "Required whenever AI systems are deployed.", sources: ["EU AI Act", "ISO 42001:2023", "DSGVO Art.22", "NIST AI RMF 1.0"] },
    { id: "p50-c01", title: "KI-Governance und Verantwortlichkeiten", titleEn: "AI Governance & Responsibilities", description: "Wir müssen eine Governance-Struktur für KI etablieren: KI-Verantwortlicher, Genehmigungs- und Risikobewertungsprozess vor dem Einsatz, Überwachung laufender KI-Systeme und Verfahren zur Außerbetriebnahme. Nicht genehmigte KI-Tools (Schatten-KI) müssen unterbunden werden.", descriptionEn: "We must establish AI governance: AI officer, approval and risk assessment process before deployment, monitoring of running AI systems, and decommissioning procedures. Unapproved AI tools (shadow AI) must be prevented.", reason: "Ohne Governance-Struktur werden KI-Systeme unkontrolliert eingesetzt, was zu Datenschutz-, Sicherheits- und Compliance-Risiken führt.", reasonEn: "Without governance structure, AI systems are deployed uncontrolled, leading to data protection, security, and compliance risks.", whenRequired: "Erforderlich für alle Organisationen mit KI-Nutzung.", whenRequiredEn: "Required for all organisations using AI.", sources: ["EU AI Act Art.9", "ISO 42001:2023", "NIST AI RMF 1.0 GOVERN"] },
    { id: "p50-c02", title: "KI-Risikobewertung und Klassifizierung", titleEn: "AI Risk Assessment & Classification", description: "Vor dem Einsatz jedes KI-Systems muss eine Risikobewertung durchgeführt werden. Die Bewertung muss umfassen: Risikostufe gemäß EU AI Act (minimal, begrenzt, hoch, unakzeptabel), Datenschutzimplikationen (DSFA bei personenbezogenen Daten), Sicherheitsrisiken, Bias-Potenzial und Auswirkungen auf betroffene Personen. Hochrisiko-KI-Systeme erfordern umfassende Dokumentation und Überwachung.", descriptionEn: "Before deploying any AI system, a risk assessment must be conducted covering: risk level per EU AI Act (minimal, limited, high, unacceptable), data protection implications (DPIA for personal data), security risks, bias potential, and impacts on affected persons. High-risk AI systems require comprehensive documentation and monitoring.", reason: "Der EU AI Act stuft KI-Systeme nach Risiko ein und verbietet bestimmte Anwendungen. Ohne Risikobewertung drohen regulatorische Sanktionen.", reasonEn: "The EU AI Act classifies AI systems by risk and prohibits certain applications. Without risk assessment, regulatory sanctions are likely.", whenRequired: "Erforderlich vor jedem KI-Einsatz.", whenRequiredEn: "Required before every AI deployment.", sources: ["EU AI Act Art.6-7, Art.9", "ISO 42001:2023", "DSGVO Art.35", "NIST AI RMF 1.0 MAP"] },
    { id: "p50-c03", title: "KI-Inventar und Transparenz", titleEn: "AI Inventory & Transparency", description: "Ein Inventar aller eingesetzten KI-Systeme muss geführt werden: Zweck, verarbeitete Datentypen, Anbieter, Risikoeinstufung, Verantwortlicher und Genehmigungsstatus. KI-Nutzung muss transparent kommuniziert werden. KI-generierte Inhalte müssen als solche gekennzeichnet werden.", descriptionEn: "An inventory of all deployed AI systems must be maintained: purpose, processed data types, provider, risk rating, responsible person, and approval status. AI usage must be transparently communicated. AI-generated content must be labelled as such.", reason: "Ohne Inventar verliert die Organisation den Überblick. Transparenz ist eine EU-AI-Act-Anforderung.", reasonEn: "Without an inventory, we lose oversight. Transparency is an EU AI Act requirement.", whenRequired: "Erforderlich sobald KI-Systeme eingesetzt werden.", whenRequiredEn: "Required whenever AI systems are deployed.", sources: ["EU AI Act Art.13, Art.50", "ISO 42001:2023", "NIST AI RMF 1.0 GOVERN"] },
    { id: "p50-c04", title: "Datenschutz und Datensicherheit bei KI", titleEn: "Data Protection & Security in AI", description: "KI-Systeme, die personenbezogene Daten verarbeiten, müssen alle DSGVO-Anforderungen erfüllen. Trainingsdaten müssen auf Datenschutzkonformität geprüft werden. Datenminimierung muss angewandt werden. Bei automatisierten Entscheidungen gemäß DSGVO Art.22 muss menschliche Intervention möglich sein. Vertrauliche Daten dürfen nicht in öffentliche KI-Dienste eingegeben werden.", descriptionEn: "AI systems processing personal data must meet all GDPR requirements. Training data must be checked for data protection compliance. Data minimisation must be applied. For automated decisions per GDPR Art.22, human intervention must be possible. Confidential data must not be entered into public AI services.", reason: "KI-Systeme verarbeiten oft große Mengen personenbezogener Daten. Ohne besondere Schutzmaßnahmen drohen DSGVO-Verstöße.", reasonEn: "AI systems often process large volumes of personal data. Without special protective measures, GDPR violations are likely.", whenRequired: "Erforderlich für alle KI-Systeme mit personenbezogenen Daten.", whenRequiredEn: "Required for all AI systems with personal data.", sources: ["DSGVO Art.5, Art.22, Art.25", "EU AI Act Art.10", "ISO 42001:2023"] },
    { id: "p50-c05", title: "Bias-Erkennung und Fairness", titleEn: "Bias Detection & Fairness", description: "KI-Systeme müssen regelmäßig auf Bias und Diskriminierung geprüft werden. Trainingsdaten müssen auf Repräsentativität und Verzerrungen untersucht werden. Metriken für Fairness müssen definiert und überwacht werden. Bei erkanntem Bias müssen Korrekturmaßnahmen eingeleitet werden.", descriptionEn: "AI systems must be regularly checked for bias and discrimination. Training data must be examined for representativeness and distortions. Fairness metrics must be defined and monitored. Corrective measures must be initiated upon detected bias.", reason: "KI-Systeme können bestehende gesellschaftliche Vorurteile verstärken. Proaktive Bias-Erkennung verhindert Diskriminierung.", reasonEn: "AI systems can amplify existing societal prejudices. Proactive bias detection prevents discrimination.", whenRequired: "Erforderlich für alle KI-Systeme, die Entscheidungen über Personen beeinflussen.", whenRequiredEn: "Required for all AI systems influencing decisions about persons.", sources: ["EU AI Act Art.10", "ISO 42001:2023", "NIST AI RMF 1.0 MEASURE"] },
    { id: "p50-c06", title: "Generative KI und LLM-Nutzung", titleEn: "Generative AI & LLM Usage", description: "Die Nutzung generativer KI (ChatGPT, Copilot etc.) muss klar geregelt sein: genehmigte Tools und Anwendungsfälle, verbotene Eingaben (vertrauliche Daten, personenbezogene Daten, Quellcode), Validierungspflicht für KI-generierte Outputs, Kennzeichnung KI-generierter Inhalte und Schulung der Nutzenden in Risiken und Best Practices.", descriptionEn: "Use of generative AI (ChatGPT, Copilot etc.) must be clearly regulated: approved tools and use cases, prohibited inputs (confidential data, personal data, source code), validation requirement for AI-generated outputs, labelling of AI-generated content, and user training in risks and best practices.", reason: "Generative KI birgt spezifische Risiken: Datenleck durch Eingaben, Halluzinationen, Copyright-Verletzungen und übermäßiges Vertrauen in Outputs.", reasonEn: "Generative AI carries specific risks: data leaks through inputs, hallucinations, copyright violations, and over-reliance on outputs.", whenRequired: "Erforderlich für alle Organisationen mit generativer KI-Nutzung.", whenRequiredEn: "Required for all organisations using generative AI.", sources: ["EU AI Act Art.50", "ISO 42001:2023", "BSI Empfehlungen zu LLM"] },
    { id: "p50-c07", title: "KI-Monitoring und kontinuierliche Überwachung", titleEn: "AI Monitoring & Continuous Oversight", description: "Produktive KI-Systeme müssen kontinuierlich überwacht werden: Performance-Metriken, Accuracy-Drift, Datendrift, unerwartete Outputs und Nutzungsverhalten. Schwellenwerte für Alarme müssen definiert sein. Bei signifikantem Drift muss eine Neubewertung und ggf. Retraining erfolgen.", descriptionEn: "Production AI systems must be continuously monitored: performance metrics, accuracy drift, data drift, unexpected outputs, and usage behaviour. Alarm thresholds must be defined. Upon significant drift, reassessment and potentially retraining must occur.", reason: "KI-Modelle degradieren über Zeit (Model Drift). Ohne Monitoring bleiben nachlassende Leistung und fehlerhafte Entscheidungen unbemerkt.", reasonEn: "AI models degrade over time (model drift). Without monitoring, declining performance and faulty decisions go unnoticed.", whenRequired: "Erforderlich für alle produktiven KI-Systeme.", whenRequiredEn: "Required for all production AI systems.", sources: ["EU AI Act Art.9(2)", "ISO 42001:2023", "NIST AI RMF 1.0 MEASURE"] },
    { id: "p50-c08", title: "Überprüfung der KI-Richtlinie", titleEn: "Review of AI Policy", description: "Diese Richtlinie muss mindestens halbjährlich überprüft werden, da sich die KI-Landschaft und Regulierung schnell entwickeln. Neue KI-Technologien, EU-AI-Act-Anforderungen und Vorfälle müssen berücksichtigt werden.", descriptionEn: "This policy must be reviewed at least semi-annually as the AI landscape and regulation are rapidly evolving. New AI technologies, EU AI Act requirements, and incidents must be considered.", reason: "Die KI-Regulierung (insbesondere EU AI Act) entwickelt sich dynamisch. Halbjährliche Überprüfung stellt die Aktualität sicher.", reasonEn: "AI regulation (especially EU AI Act) is developing dynamically. Semi-annual review ensures currency.", whenRequired: "Immer erforderlich, halbjährlich.", whenRequiredEn: "Always required, semi-annually.", sources: ["EU AI Act", "ISO 42001:2023", "NIST AI RMF 1.0"] },
    { id: "p50-c09", title: "KI-gestützte Entscheidungen und Automatisierung", titleEn: "AI-Assisted Decisions & Automation", description: "KI-Systeme dürfen keine vollautomatisierten Entscheidungen treffen, die wesentliche Auswirkungen auf Personen haben, ohne menschliche Überprüfung (Human-in-the-Loop). Entscheidungskriterien müssen nachvollziehbar dokumentiert sein. Betroffene Personen müssen über KI-Beteiligung informiert werden und das Recht auf menschliche Überprüfung haben.", descriptionEn: "AI systems must not make fully automated decisions with significant impacts on persons without human review (Human-in-the-Loop). Decision criteria must be traceably documented. Affected persons must be informed about AI involvement and have the right to human review.", reason: "DSGVO Art.22 und EU AI Act fordern menschliche Aufsicht bei automatisierten Entscheidungen.", reasonEn: "GDPR Art.22 and EU AI Act require human oversight for automated decisions.", whenRequired: "Erforderlich für alle KI-gestützten Entscheidungsprozesse.", whenRequiredEn: "Required for all AI-assisted decision processes.", sources: ["DSGVO Art.22", "EU AI Act Art.14", "ISO 42001:2023"] },
    { id: "p50-c10", title: "KI-Modell-Lifecycle, Versionierung und Reproduzierbarkeit", titleEn: "AI Model Lifecycle, Versioning & Reproducibility", description: "KI-Modelle müssen über ihren gesamten Lebenszyklus verwaltet werden: Entwicklung/Auswahl, Training, Validierung, Deployment, Monitoring, Re-Training und Decommissioning. Alle Modelle müssen versioniert und mit vollständiger Dokumentation ihrer Trainingsdaten, Hyperparameter und Leistungsmetriken gespeichert werden. Jede Modellversion muss reproduzierbar sein. Rollback auf frühere Modellversionen muss jederzeit möglich sein. Model-Drift muss überwacht und bei Verschlechterung Maßnahmen eingeleitet werden.", descriptionEn: "AI models must be managed across their entire lifecycle: development/selection, training, validation, deployment, monitoring, re-training, and decommissioning. All models must be versioned and stored with complete documentation of training data, hyperparameters, and performance metrics. Each version must be reproducible. Rollback to previous versions must be possible at any time. Model drift must be monitored and measures initiated upon deterioration.", reason: "Ohne Versionierung und Lifecycle-Management sind Fehleranalysen, Audits und Qualitätssicherung von KI-Modellen unmöglich.", reasonEn: "Without versioning and lifecycle management, error analysis, audits, and quality assurance of AI models are impossible.", whenRequired: "Erforderlich für alle selbst trainierten oder betriebenen KI-Modelle.", whenRequiredEn: "Required for all self-trained or operated AI models.", sources: ["EU AI Act Art.9, Art.12", "ISO 42001:2023", "BSI AIC4", "NIST AI RMF 1.0 MANAGE"] },
    { id: "p50-c11", title: "KI-Sicherheitstests und Red-Teaming", titleEn: "AI Security Testing & Red Teaming", description: "KI-Systeme müssen vor dem Einsatz Sicherheitstests unterzogen werden: Adversarial Testing, Prompt-Injection-Tests, Jailbreak-Versuche, Data-Poisoning-Bewertung und Robustheitstests. Für Hochrisiko-KI-Systeme müssen Red-Team-Übungen durchgeführt werden.", descriptionEn: "AI systems must undergo security testing before deployment: adversarial testing, prompt injection tests, jailbreak attempts, data poisoning assessment, and robustness tests. For high-risk AI systems, red team exercises must be conducted.", reason: "KI-Systeme haben spezifische Angriffsvektoren (Prompt Injection, Adversarial Examples), die durch klassische Tests nicht abgedeckt werden.", reasonEn: "AI systems have specific attack vectors (prompt injection, adversarial examples) not covered by classical testing.", whenRequired: "Erforderlich für alle produktiv eingesetzten KI-Systeme.", whenRequiredEn: "Required for all productively deployed AI systems.", sources: ["EU AI Act Art.9", "NIST AI RMF 1.0 MEASURE", "OWASP LLM Top 10"] },
    { id: "p50-c12", title: "KI-Ethik und verantwortungsvoller Einsatz", titleEn: "AI Ethics & Responsible Use", description: "Wir müssen ethische Grundsätze für den KI-Einsatz definieren: Fairness, Transparenz, Nicht-Diskriminierung, Menschenwürde und Nachhaltigkeit. Ein Ethik-Review muss für KI-Anwendungen mit gesellschaftlicher Auswirkung durchgeführt werden. Verbotene Anwendungen gemäß EU AI Act müssen explizit ausgeschlossen werden.", descriptionEn: "We must define ethical principles for AI use: fairness, transparency, non-discrimination, human dignity, and sustainability. An ethics review must be conducted for AI applications with societal impact. Prohibited applications per EU AI Act must be explicitly excluded.", reason: "Ohne ethische Leitlinien können KI-Systeme diskriminierend oder gesellschaftlich schädlich eingesetzt werden.", reasonEn: "Without ethical guidelines, AI systems can be used discriminatorily or in socially harmful ways.", whenRequired: "Erforderlich für alle KI-Anwendungen.", whenRequiredEn: "Required for all AI applications.", sources: ["EU AI Act Art.5", "ISO 42001:2023", "OECD AI Principles"] },
    { id: "p50-c13", title: "Copyright und geistiges Eigentum bei KI", titleEn: "Copyright & Intellectual Property in AI", description: "Wir müssen Regelungen für geistiges Eigentum im Zusammenhang mit KI definieren: Urheberrecht an KI-generierten Inhalten, Nutzung urheberrechtlich geschützter Daten für Training, Lizenzierung von KI-Modellen und Haftung bei Urheberrechtsverletzungen durch KI-Outputs.", descriptionEn: "We must define regulations for intellectual property related to AI: copyright of AI-generated content, use of copyrighted data for training, licensing of AI models, and liability for copyright infringement by AI outputs.", reason: "Die Rechtslage bei KI-generiertem Content ist unklar. Ohne Regelungen riskiert die Organisation IP-Verletzungen.", reasonEn: "The legal situation for AI-generated content is unclear. Without regulations, we risk IP violations.", whenRequired: "Erforderlich für alle Organisationen, die KI-generierte Inhalte nutzen.", whenRequiredEn: "Required for all organisations using AI-generated content.", sources: ["EU AI Act", "UrhG", "ISO 42001:2023"] },
    { id: "p50-c14", title: "KI-Anbieter-Zusatzanforderungen", titleEn: "AI Provider Additional Requirements", description: "Für externe KI-Dienste gelten zusätzlich zu den allgemeinen Lieferantenanforderungen (siehe p42/p43) folgende KI-spezifische Anforderungen: Datenverarbeitungstransparenz, Opt-out für Trainingsdatennutzung, Modell-Update-Benachrichtigungen und Verfügbarkeitsgarantien. KI-Anbieter müssen in das Third-Party Risk Assessment gemäß p43 einbezogen werden.", descriptionEn: "For external AI services, in addition to general supplier requirements (see p42/p43), the following AI-specific requirements apply: data processing transparency, opt-out for training data use, model update notifications, and availability guarantees. AI providers must be included in the third-party risk assessment per p43.", reason: "KI-Anbieter haben spezifische Risiken (z.B. Nutzung von Kundendaten für Training), die über normale Lieferantenrisiken hinausgehen.", reasonEn: "AI providers have specific risks (e.g., using customer data for training) that go beyond normal supplier risks.", whenRequired: "Erforderlich für alle externen KI-Dienste.", whenRequiredEn: "Required for all external AI services.", sources: ["EU AI Act Art.28", "ISO 42001:2023", "DSGVO Art.28"] },
    { id: "p50-c15", title: "KI-Code-Generierung und Entwicklungsunterstützung", titleEn: "AI Code Generation & Development Support", description: "Die Nutzung von KI-gestützten Entwicklungstools (GitHub Copilot, CodeWhisperer etc.) muss geregelt sein: nur genehmigte Tools, kein proprietärer Quellcode als Input, Validierungspflicht für generierten Code, Sicherheitsscans für KI-generierten Code und Lizenzprüfung für generierte Code-Snippets. Für sichere Entwicklungsstandards bei KI-generiertem Code siehe p47 (Sichere Entwicklung).", descriptionEn: "Use of AI-assisted development tools (GitHub Copilot, CodeWhisperer etc.) must be regulated: only approved tools, no proprietary source code as input, validation requirement for generated code, security scans for AI-generated code, and licence checks for generated code snippets. For secure development standards for AI-generated code see p47 (Secure Development).", reason: "KI-generierter Code kann Sicherheitslücken und Lizenzverletzungen enthalten.", reasonEn: "AI-generated code can contain security vulnerabilities and licence violations.", whenRequired: "Erforderlich für alle Entwicklungsteams mit KI-Tools.", whenRequiredEn: "Required for all development teams with AI tools.", sources: ["ISO 27001:2022 A.8.28", "OWASP LLM Top 10", "ISO 42001:2023"] },
    { id: "p50-c16", title: "KI und Barrierefreiheit", titleEn: "AI & Accessibility", description: "KI-Systeme müssen barrierefrei gestaltet sein und dürfen keine Gruppen benachteiligen. Die Ausgaben von KI-Systemen müssen in zugänglichen Formaten bereitgestellt werden. Sprachmodelle müssen verschiedene Sprachen und Dialekte angemessen unterstützen.", descriptionEn: "AI systems must be designed accessibly and must not disadvantage any groups. AI system outputs must be provided in accessible formats. Language models must adequately support different languages and dialects.", reason: "KI-Systeme können Barrierefreiheit verbessern, aber auch neue Barrieren schaffen, wenn sie nicht inklusiv gestaltet sind.", reasonEn: "AI systems can improve accessibility but also create new barriers if not inclusively designed.", whenRequired: "Erforderlich für alle öffentlich zugänglichen KI-Systeme.", whenRequiredEn: "Required for all publicly accessible AI systems.", sources: ["EU AI Act", "BFSG", "ISO 42001:2023"] },
    { id: "p50-c17", title: "KI-Vorfallmanagement und Incident-Response", titleEn: "AI Incident Management & Response", description: "KI-spezifische Vorfälle müssen im Vorfallmanagement berücksichtigt werden: Bias-Vorfälle, Halluzinationen mit Geschäftsauswirkung, Datenlecks durch KI-Eingaben, Prompt-Injection-Angriffe, Adversarial Attacks, Modellmanipulation, Datenvergiftung und Missbrauch von KI-Systemen. Für jeden KI-Vorfalltyp müssen Eskalations- und Reaktionsverfahren definiert sein. Notfallpläne müssen die sofortige Deaktivierung oder den Fallback auf nicht-KI-basierte Prozesse vorsehen. Für allgemeine Incident-Response-Prozesse siehe p30 (Incident Response).", descriptionEn: "AI-specific incidents must be considered in incident management: bias incidents, hallucinations with business impact, data leaks through AI inputs, prompt injection attacks, adversarial attacks, model manipulation, data poisoning, and misuse of AI systems. Escalation and response procedures must be defined for each AI incident type. Emergency plans must provide for immediate deactivation or fallback to non-AI processes. For general incident response processes see p30 (Incident Response).", reason: "KI-Vorfälle erfordern spezialisierte Reaktionsverfahren, die über klassische IT-Incident-Response hinausgehen. Klassisches Vorfallmanagement deckt KI-spezifische Szenarien nicht ab.", reasonEn: "AI incidents require specialised response procedures that go beyond classic IT incident response. Classical incident management does not cover AI-specific scenarios.", whenRequired: "Erforderlich für alle Organisationen mit KI-Systemen.", whenRequiredEn: "Required for all organisations with AI systems.", sources: ["EU AI Act Art.9, Art.62", "ISO 42001:2023", "BSI AIC4", "NIST AI RMF 1.0"] },
    { id: "p50-c18", title: "KI-Dokumentation und Nachvollziehbarkeit", titleEn: "AI Documentation & Traceability", description: "Alle KI-Systeme müssen umfassend dokumentiert sein: Zweck, Trainingsdaten, Architektur, Performance-Metriken, bekannte Einschränkungen, Risikobewertung und Verantwortlichkeiten. Für Hochrisiko-KI-Systeme muss eine technische Dokumentation gemäß EU AI Act erstellt werden.", descriptionEn: "All AI systems must be comprehensively documented: purpose, training data, architecture, performance metrics, known limitations, risk assessment, and responsibilities. For high-risk AI systems, technical documentation per EU AI Act must be created.", reason: "Ohne Dokumentation sind KI-Entscheidungen nicht nachvollziehbar und Compliance-Anforderungen nicht erfüllbar.", reasonEn: "Without documentation, AI decisions are not traceable and compliance requirements cannot be met.", whenRequired: "Erforderlich für alle KI-Systeme, insbesondere Hochrisiko.", whenRequiredEn: "Required for all AI systems, especially high-risk.", sources: ["EU AI Act Art.11", "ISO 42001:2023", "NIST AI RMF 1.0 GOVERN"] },
  ],
};
